/// <summary>
/// Handles the filter settings for the <c>METTransferOrderExtractScreen</c> form.
/// </summary>
public class METTransferOrderExtractScreenParameters
{
    METRoute                        route;
    InventLocationId                fromWarehouse;
    InventLocationId                toWarehouse;
    InventTransferShipDate          shippingDateConfirmedFrom;
    InventTransferShipDate          shippingDateConfirmedTo;
    METFilterCodeone                category;

    METOrderExtractStatus           extracted;

    private static int CurrentVersion = 2;

    #LOCALMACRO.CurrentList
        route,
        fromWarehouse,
        toWarehouse,
        shippingDateConfirmedFrom,
        shippingDateConfirmedTo,
        extracted,
        category
    #ENDMACRO

}

