    /// <summary>
    ///    Initializes a new instance of the <c>METTransferOrderExtractScreenParameters</c> class.
    /// </summary>
    /// <returns>
    ///    A new instance of the <c>METTransferOrderExtractScreenParameters</c> class.
    /// </returns>
    public static METTransferOrderExtractScreenParameters construct()
    {
        METTransferOrderExtractScreenParameters orderExtractScreenParameters;

        orderExtractScreenParameters = new METTransferOrderExtractScreenParameters();

        return orderExtractScreenParameters;
    }

/// <summary>
/// Parameter for route.
/// </summary>
/// <param name = "_route">METRoute</param>
/// <returns>route</returns>
public METRoute parmRoute(
    METRoute _route = route)
{
    route = _route;
    return route;
}

/// <summary>
/// Parameter for from wharehouse.
/// </summary>
/// <param name = "_fromWarehouse">Warehouse</param>
/// <returns>warehouse</returns>
public InventLocationId parmFromWarehouse(
    InventLocationId _fromWarehouse = fromWarehouse)
{
    fromWarehouse = _fromWarehouse;
    return fromWarehouse;
}

/// <summary>
/// Parameter for toWarehouse.
/// </summary>
/// <param name = "_toWarehouse">Route</param>
/// <returns>warehouse</returns>
public InventLocationId parmToWarehouse(
    InventLocationId _toWarehouse = toWarehouse)
{
    toWarehouse = _toWarehouse;
    return toWarehouse;
}

/// <summary>
/// Parameter for ShippingDateConfirmed.
/// </summary>
/// <param name = "_date">ShippingDateConfirmedFrom</param>
/// <returns>date</returns>
public InventTransferShipDate parmShippingDateConfirmFrom(
    InventTransferShipDate _date = shippingDateConfirmedFrom)
{
    shippingDateConfirmedfrom = _date;
    return shippingDateConfirmedFrom;
}

/// <summary>
/// Parameter for ShippingDateConfirmed.
/// </summary>
/// <param name = "_date">ShippingDateConfirmed</param>
/// <returns>date</returns>
public InventTransferShipDate parmShippingDateConfirmTo(
    InventTransferShipDate _date = shippingDateConfirmedTo)
{
    shippingDateConfirmedTo = _date;
    return shippingDateConfirmedTo;
}

/// <summary>
/// Parameter for Warehouse category.
/// </summary>
/// <param name = "_category">Warehouse category</param>
/// <returns>date</returns>
public METFilterCodeone parmCategory(
    METFilterCodeone _category = category)
{
    category = _Category;
    return category;
}

/// <summary>
/// Parameter for extracted filter.
/// </summary>
/// <param name = "_extracted">NoYes</param>
/// <returns>NoYes</returns>
public METOrderExtractStatus parmExtracted(
    METOrderExtractStatus _extracted = extracted)
{
    extracted = _extracted;
    return extracted;
}

    /// <summary>
    /// Loads the last values for the form name.
    /// </summary>
    /// <param name="_formName">
    /// The form name of the form.
    /// </param>
    /// <remarks>
    /// The default values are used if there is nothing to load.
    /// </remarks>
    public void loadLastValue(identifierName _formName)
    {
        container packedForm;
        Version version;

        packedForm = xSysLastValue::getValue(curext(), curUserId(), UtilElementType::Form, _formName);

        version = conpeek(packedForm, 1);

        if (version == CurrentVersion)
        {
            [version, #CurrentList] = packedForm;
        }
    }

/// <summary>
/// Saves the last values for the form name.
/// </summary>
/// <param name="_formName">
/// The form name of the form.
/// </param>
public void saveLastValue(identifierName _formName)
{
    xSysLastValue::putValue([CurrentVersion, #CurrentList], curext(), curUserId(), UtilElementType::Form, _formName);
}
